DO $$
DECLARE
  rec RECORD;
  cur_viewer INT;
  cur_progress INT;
  cur_rating INT;
BEGIN
  FOR rec IN SELECT * FROM watch_events ORDER BY event_id LOOP
    SELECT viewer_id, progress_pct, rating INTO cur_viewer, cur_progress, cur_rating
    FROM watch_sessions WHERE content_id = rec.content_id;

    IF rec.action_type = 1 AND cur_progress < 100 THEN
      UPDATE watch_sessions
      SET viewer_id = rec.user_id, progress_pct = 25
      WHERE content_id = rec.content_id;
    ELSIF rec.action_type = 2 AND cur_viewer = rec.user_id AND cur_progress < 100 THEN
      UPDATE watch_sessions
      SET progress_pct = 100
      WHERE content_id = rec.content_id;
    ELSIF rec.action_type = 3 AND cur_progress = 100 AND cur_rating IS NULL THEN
      UPDATE watch_sessions
      SET rating = rec.stars
      WHERE content_id = rec.content_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM watch_sessions ORDER BY content_id;
